INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁钰", "aliases": ["明景帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明景帝，正統14年（1449年）九月，朱祁钰即皇帝位。", "biography": null, "status": "draft", "id": "beac1b51-89b3-5024-bf3a-2d45bc5afe2b"}, {"name": "王诚（明景帝朝宦官）", "aliases": ["太監王誠"], "era": "明", "birth_year": null, "death_year": null, "description": "王诚（明景帝朝宦官）会同法司和刑科复核囚案。", "biography": null, "status": "draft", "id": "f74b9c4f-f48f-5ef9-a25c-d63c79e31ce0"}, {"name": "朱梃", "aliases": ["朱梴"], "era": "明", "birth_year": null, "death_year": null, "description": "朱梃获授翰林院世袭五经博士。", "biography": null, "status": "draft", "id": "73b5f09a-a2fd-552f-8c33-a1642bbcc3f9"}, {"name": "廖庄", "aliases": ["廖莊"], "era": "明", "birth_year": null, "death_year": null, "description": "廖庄因请求恢复沂王储位而受杖刑。", "biography": null, "status": "draft", "id": "6446e231-1c9c-5a33-8b28-2b7b977963e8"}, {"name": "朱见深", "aliases": ["明宪宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宪宗，天順8年（1464年）正月，朱见深即皇帝位。", "biography": null, "status": "draft", "id": "71fde383-1de5-538d-bb25-2cc9e4cc7d1c"}, {"name": "章纶", "aliases": ["章綸"], "era": "明", "birth_year": null, "death_year": null, "description": "章纶因上奏请恢复储位而被下狱。", "biography": null, "status": "draft", "id": "575a8a1a-e1fc-564b-90c7-100e40788aa2"}, {"name": "钟同", "aliases": ["鍾同", "鐘同"], "era": "明", "birth_year": null, "death_year": null, "description": "钟同因上奏请恢复储位而被下狱。", "biography": null, "status": "draft", "id": "424bc66c-e972-5b36-90b0-7a5efc9acf79"}, {"name": "方瑛", "aliases": ["參將方瑛"], "era": "明", "birth_year": null, "death_year": null, "description": "方瑛参与贵州战事。", "biography": null, "status": "draft", "id": "02981879-a0e2-5f34-81d2-beadecd41264"}, {"name": "石璞（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统13年（年号对照1448年）五月，石璞出任工部尚书。", "biography": null, "status": "draft", "id": "cf73a116-9338-5fa8-81a2-a33c0b3a9657"}, {"name": "杭氏（明景帝肃孝皇后）", "aliases": ["景帝杭皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "杭氏（明景帝肃孝皇后）获立为皇后。", "biography": null, "status": "draft", "id": "0ea826ff-d313-57cd-82c8-8bd110c3d720"}, {"name": "周冕（周敦颐后人）", "aliases": ["裔孫冕"], "era": "明", "birth_year": null, "death_year": null, "description": "周冕（周敦颐后人）获授世袭五经博士。", "biography": null, "status": "draft", "id": "04338900-cbb0-5c28-ae7c-df2f2c77d157"}, {"status": "draft", "name": "朱熹", "aliases": [], "era": "南宋", "birth_year": null, "death_year": null, "description": "宋学者，幼从延平李侗学，曾中进士任同安主簿，后在武夷山讲学，1159年受召未赴。", "biography": null, "id": "47e4bc10-b7b0-5c05-98d0-161bf8794bf4"}, {"status": "draft", "name": "周敦颐", "aliases": [], "era": "北宋", "birth_year": null, "death_year": null, "description": "宋国子博士、虔州通判，曾任合州判官，赵抃称其字周茂叔。", "biography": null, "id": "ac17a02d-482d-5fd2-af84-653ffb73f32f"}]'::jsonb)
