ation_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "37c83c44-4843-5562-8b0a-1604704e9191"}, {"title": "明景帝在南郊祈雨", "description": "景泰六年五月己巳，明景帝在南郊祈雨。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年五月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3d7200c4-0d62-520a-b099-837808b2b75b"}, {"title": "明廷授朱熹后人朱梃世袭五经博士", "description": "景泰六年六月乙亥，明廷任命宋代学者朱熹的后人朱梃为翰林院世袭五经博士。《职官志》将其名字写作朱梴。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年六月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "faed102f-5775-5e14-a894-8d39a3bddbd2"}, {"title": "黄河在开封决口", "description": "景泰六年六月癸未，黄河在开封决口。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年六月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "89261652-6ea4-59c8-95f1-a2cf92093fdf"}, {"title": "沙湾黄河决口处的堤坝完工", "description": "景泰六年七月乙亥，沙湾黄河决口处的堤坝完工。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年七月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "802b41c3-1f1a-5384-94d8-aadadf8e60e7"}, {"title": "明廷因南京接连发生灾异，命群臣修省", "description": "景泰六年七月庚寅，朝廷以南京屡次出现灾异为由，下令群臣反省政事。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年七月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0e7bc18c-bedf-509b-85df-da52182a9d6b"}, {"title": "廖庄因请求恢复朱见深太子之位而受杖刑", "description": "景泰六年八月庚申，南京大理少卿廖庄因请求让沂王朱见深重新成为皇太子，在宫门前遭受杖刑。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年八月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05579eb6-5aa0-550b-92a9-8ee9d943231d"}, {"title": "章纶和钟同在监狱中受杖刑", "description": "景泰六年八月庚申，明廷也在监狱中对章纶、钟同施行杖刑，本纪随后记下了钟同之死。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年八月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "12b1570e-9a6f-597a-aa2a-bc38b412f01e"}, {"title": "钟同在狱中受杖刑后去世", "description": "景泰六年八月，监察御史钟同在狱中遭受杖刑后去世。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "91a9acde-b9d1-5422-9211-abf5c958be35"}, {"title": "明廷发米麦一百余万石赈济苏州和松江饥民", "description": "景泰六年九月乙亥，朝廷发放米麦一百余万石，救济苏州和松江的饥民。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年九月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e20a0c2d-3069-5a66-865f-3f09ea754935"}, {"title": "明廷豁免陕西灾区税粮", "description": "景泰六年十月戊午，朝廷免除陕西受灾地区应缴的税粮。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年十月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8ad8bd46-68f1-54ee-b065-1703dbdb9306"}, {"title": "方瑛任总兵官，奉命征讨湖广起事苗民", "description": "景泰六年十一月乙亥，明廷任命南和伯方瑛为平蛮将军、总兵官，令他率军征讨湖广起事的苗民。", "start_year": 1455, "end_year": 1455, "time_original": "景泰六年十一月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2b760ef2-a754-5796-930c-2f999d8a84a7"}, {"title": "明廷豁免南直隶灾区秋粮", "description": "景泰六年十二月己巳，朝廷免除南直隶受灾地区应缴纳的秋粮。", "start_year": 1456, "end_year": 1456, "time_original": "景泰六年十二月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7f08715e-0b1d-5f60-8b1f-d93279ebae21"}, {"title": "琉球中山、暹罗、哈密和满剌加入贡", "description": "景泰六年，琉球中山、暹罗、哈密和满剌加入贡。 按原历纪年，事情发生在公元1455至1456年之间。", "start_year": null, "end_year": null, "time_original": "景泰六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "02d2bc0e-127e-51c6-81fa-a7d35d2862c0"}, {"title": "石璞安抚湖广", "description": "景泰7年（年号对照1456年）正月，石璞安抚湖广。", "start_year": 1456, "end_year": 1456, "time_original": "景泰7年（年号对照1456年）正月；公元年核为1456年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "fc7868fe-2bc1-5bfb-b402-b66db6aa666f"}, {"title": "明景帝在南郊祭祀天地", "description": "景泰七年正月壬午，明景帝朱祁钰在南郊举行祭祀天地的大典。", "start_year": 1456, "end_year": 1456, "time_original": "景泰七年正月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b4012912-f222-5e39-9e02-851dfdf5a059"}, {"title": "明景帝皇后杭氏去世", "description": "景泰七年二月庚申，明景帝皇后杭氏去世。", "start_year": 1456, "end_year": 1456, "time_original": "景泰七年二月庚申